import { redact } from './redact';

export async function buildPack(logDir: string, out: string): Promise<Manifest> {
  const runs = (await readRuns(logDir)).map(redact);
  const sections = {
    'CC8.1-change-management.csv': changeRows(runs),
    'CC7.1-vulnerability-scans.csv': scanRows(runs),
    'CC6.1-deploy-approvals.csv': approvalRows(runs),
    'exceptions.md': exceptionReport(runs),
  };
  const files = await writeSorted(out, sections);
  const manifest = { generatedFrom: logDir, runs: runs.length, files: files.map((f) => ({ path: f.path, sha256: f.sha256 })) };
  await Bun.write(`${out}/MANIFEST.json`, JSON.stringify(manifest, null, 2));
  return manifest;
}

test('pack is deterministic', async () => {
  const a = await buildPack(FIXTURE, tmp('a'));
  const b = await buildPack(FIXTURE, tmp('b'));
  expect(a.files).toEqual(b.files);
});
test('no secret survives into the pack', async () => {
  await buildPack(FIXTURE_WITH_SECRETS, tmp('c'));
  expect(await grepDir(tmp('c'), SECRET_SHAPES)).toEqual([]);
});
